DO $$ DECLARE new_id bigint; BEGIN IF EXISTS (SELECT 1 FROM poems WHERE author_id = 1684 AND name = 'Tôi yêu em') THEN RETURN; END IF;
INSERT INTO poems (name, author_id, language, year, content, meaning, source_url, is_deleted, created_at, updated_at, created_by, updated_by) VALUES ( 'Tôi yêu em', 1684, 'Việt', 1829, $content$Я вас любил: любовь еще, быть может, В душе моей угасла не совсем; Но пусть она вас больше не тревожит; Я не хочу печалить вас ничем.
Я вас любил безмолвно, безнадежно, То робостью, то ревностью томим; Я вас любил так искренно, так нежно, Как дай вам бог любимой быть другим.$content$, $meaning$Tôi đã yêu em: tình yêu hãy còn, có lẽ là Trong lòng tôi (nó) đã không tắt hẳn; Nhưng thôi, hãy để nó chẳng quấy rầy em thêm nữa. Tôi không muốn làm phiền muộn em bởi bất cứ điều gì.
Tôi đã yêu em lặng thầm, không hy vọng, Bị giày vò khi thì bởi sự rụt rè, khi thì bởi nỗi hờn ghen. Tôi đã yêu em chân thành đến thế, dịu dàng đến thế, Cầu Chúa cho em vẫn là người được yêu dấu như thế bởi người khác.$meaning$, 'https://www.thivien.net/Aleksandr-Pushkin/T%C3%B4i-y%C3%AAu-em/poem-to-UkdFjJeg6pwDSfG5oNA', false, now(), now(), 'THIVIEN-MANUAL', 'THIVIEN-MANUAL' ) RETURNING id INTO new_id;
INSERT INTO poem_translations (poem_id, translator, content, sort_order, is_deleted, created_at, updated_at, created_by, updated_by) VALUES ( new_id, 'Thuý Toàn', $tt$Tôi yêu em: đến nay chừng có thể. Ngọn lửa tình chưa hẳn đã tàn phai; Nhưng không để em bận lòng thêm nữa, Hay hồn em phải gợn bóng u hoài.
Tôi yêu em âm thầm không hy vọng, Lúc rụt rè, khi hậm hực lòng ghen, Tôi yêu em, yêu chân thành đằm thắm, Cầu em được người tình như tôi đã yêu em.$tt$, 0, false, now(), now(), 'THIVIEN-MANUAL', 'THIVIEN-MANUAL' ); END $$;
